    expect(readIntakeRequests(root).map(record => [record.record, record.requests.length])).toEqual([
      ['data/enterprise/intake/2026-09-29-010000-aaaa', 2],
      ['data/enterprise/intake/2026-09-29-030000-cccc', 0],
